-- Question 1.4: population inside the user's mainland PDRY polygon.
SELECT
    MIN(latitude) AS min_latitude,
    MIN(longitude) AS min_longitude,
    MAX(latitude) AS max_latitude,
    MAX(longitude) AS max_longitude,
    CAST(SUM(population) AS INTEGER) AS population
FROM yemen_2020
WHERE type = 'total_population'
  AND ST_Within(
    ST_Point(longitude, latitude),
    ST_Polygon('POLYGON ((52.0367572 19.0380163,48.8542839 18.2415236,46.3943132 15.6662751,45.6001744 15.1482122,45.5175907 14.9586284,45.3777439 14.9029019,45.3927596 14.7817204,45.462983 14.7691749,45.533926 14.6486963,45.6314748 14.7173896,45.7996804 14.6654671,45.8423921 14.53109,45.9272703 14.31611,45.3974468 14.0655083,45.1458282 13.9393359,44.8099498 13.6747257,44.3877519 13.4743055,44.3179937 13.226432,44.0349846 13.0815541,43.7790531 13.0464094,43.6652803 12.9051614,43.5083531 12.6790432,43.8792878 12.6086202,44.1207341 12.5885826,44.4179118 12.6661557,44.6012894 12.7536269,44.7983942 12.7310735,45.0090736 12.7634731,45.1071029 12.9164714,45.428819 13.0732949,45.6657739 13.3092284,46.4726884 13.4417768,47.415224 13.6507548,47.9416071 14.0296952,48.6488457 14.05412,49.080711 14.4288885,49.9767517 14.8508054,52.2615624 15.5949357,52.2121304 15.9760222,52.3631593 16.2175478,52.7053094 16.4559139,53.017426 16.5726327,53.1667669 16.6243416,52.7687262 17.0546675,52.7938255 17.3412036,51.9151148 18.5834771,52.0367572 19.0380163))')
  );
